CREATE TABLE "managers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(50) UNIQUE,
  "password_hash" varchar(255),
  "role" varchar(20) DEFAULT 'sales_admin'
);

CREATE TABLE "chat_sessions" (
  "id" varchar(64) PRIMARY KEY,
  "current_stage" varchar(40) DEFAULT 'IDLE',
  "mode" varchar(50),
  "negotiate_active" boolean,
  "created_at" timestamp,
  "updated_at" timestamp,
  "customer_id" integer NOT NULL
);

CREATE TABLE "customers" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "phone_number" varchar(20) UNIQUE,
  "full_name" varchar(80),
  "cccd" varchar(20),
  "created_at" timestamp,
  "updated_at" timestamp
);

CREATE TABLE "messages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_id" varchar(64) NOT NULL,
  "role" varchar(20) NOT NULL,
  "content" text NOT NULL,
  "tool_calls" json,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "contracts" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" integer NOT NULL,
  "variant_id" integer NOT NULL,
  "session_id" varchar(64),
  "total_amount" decimal(15,2),
  "pdf_url" text,
  "status" varchar(20) DEFAULT 'DRAFT',
  "created_at" timestamp
);

CREATE TABLE "maintenance_reminders" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" integer NOT NULL,
  "contract_id" integer,
  "target_km" integer,
  "scheduled_date" date,
  "status" varchar(20),
  "created_at" timestamp
);

CREATE TABLE "brands" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(80) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "vehicle_types" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(80) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "vehicle_models" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "brand_id" smallint NOT NULL,
  "name" varchar(120),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "vehicle_variants" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "model_id" integer,
  "vehicle_type_id" smallint,
  "product_code" varchar(64) UNIQUE,
  "version_label" varchar(40),
  "model_year" smallint CHECK (model_year BETWEEN 1900 AND 2200),
  "assembly_type" smallint CHECK (assembly_type IN (1, 2)),
  "launch_date" date,
  "wheel_formula" varchar(12),
  "curb_mass_kg" decimal(8,2) CHECK (curb_mass_kg > 0),
  "curb_mass_basis" varchar(40),
  "payload_kg" decimal(8,2) CHECK (payload_kg >= 0),
  "gross_mass_kg" decimal(8,2) CHECK (gross_mass_kg > 0),
  "seat_count" smallint CHECK (seat_count > 0),
  "segment_id" smallint,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_load_alternatives" (
  "variant_id" integer NOT NULL,
  "kind" smallint NOT NULL CHECK (kind IN (1, 2)),
  "alternative_no" smallint NOT NULL CHECK (alternative_no > 0),
  "mass_kg" decimal(8,2) NOT NULL CHECK (mass_kg > 0),
  "qualifier" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "kind", "alternative_no")
);

CREATE TABLE "segments" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(40) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_dimensions" (
  "variant_id" integer NOT NULL,
  "scope" smallint NOT NULL CHECK (scope IN (1, 2, 3, 4)),
  "alternative_no" smallint NOT NULL CHECK (alternative_no > 0) DEFAULT 1,
  "qualifier" text,
  "length_mm" integer CHECK (length_mm > 0),
  "width_mm" integer CHECK (width_mm > 0),
  "height_mm" integer CHECK (height_mm > 0),
  "volume_m3" decimal(8,3) CHECK (volume_m3 > 0),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "scope", "alternative_no")
);

CREATE TABLE "variant_chassis" (
  "variant_id" integer PRIMARY KEY,
  "front_overhang_mm" integer CHECK (front_overhang_mm >= 0),
  "rear_overhang_mm" integer CHECK (rear_overhang_mm >= 0),
  "ground_clearance_mm" integer CHECK (ground_clearance_mm >= 0),
  "turning_radius_m" decimal(5,2) CHECK (turning_radius_m > 0),
  "steering_system" text,
  "brake_assist" text,
  "fuel_tank_l" smallint CHECK (fuel_tank_l > 0),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_axle_spacings" (
  "variant_id" integer NOT NULL,
  "position" smallint NOT NULL CHECK (position > 0),
  "distance_mm" integer NOT NULL CHECK (distance_mm > 0),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "position")
);

CREATE TABLE "variant_axles" (
  "variant_id" integer NOT NULL,
  "position" smallint NOT NULL CHECK (position > 0),
  "designation" varchar(80),
  "rated_load_kg" decimal(8,2) CHECK (rated_load_kg > 0),
  "tread_mm" integer CHECK (tread_mm > 0),
  "outside_tread_mm" integer CHECK (outside_tread_mm > 0),
  "final_drive_ratio" decimal(7,4) CHECK (final_drive_ratio > 0),
  "suspension_system" text,
  "leaf_count" smallint CHECK (leaf_count > 0),
  "helper_leaf_count" smallint CHECK (helper_leaf_count >= 0),
  "brake_system" text,
  "tire_size" varchar(32),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "position")
);

CREATE TABLE "engines" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(64) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_engines" (
  "variant_id" integer PRIMARY KEY,
  "engine_id" integer,
  "displacement_cc" integer CHECK (displacement_cc > 0),
  "max_power_kw" decimal(7,2) CHECK (max_power_kw > 0),
  "power_rpm" smallint CHECK (power_rpm > 0),
  "max_torque_nm" decimal(8,2) CHECK (max_torque_nm > 0),
  "torque_rpm_min" smallint CHECK (torque_rpm_min > 0),
  "torque_rpm_max" smallint CHECK (torque_rpm_max > 0),
  "emission_standard" varchar(24),
  "exhaust_treatment" varchar(120),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  CHECK (torque_rpm_min IS NULL OR torque_rpm_max IS NULL OR torque_rpm_min <= torque_rpm_max)
);

CREATE TABLE "transmissions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "designation" varchar(80) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_transmissions" (
  "variant_id" integer PRIMARY KEY,
  "transmission_id" integer,
  "transmission_type" smallint CHECK (transmission_type IN (1, 2, 3, 4)),
  "forward_gear_count" smallint CHECK (forward_gear_count > 0),
  "reverse_gear_count" smallint CHECK (reverse_gear_count > 0),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_gear_ratios" (
  "variant_id" integer NOT NULL,
  "gear_no" smallint NOT NULL CHECK (gear_no <> 0),
  "ratio" decimal(8,4) NOT NULL CHECK (ratio > 0),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "gear_no")
);

CREATE TABLE "equipment" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(80) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_equipment" (
  "variant_id" integer NOT NULL,
  "equipment_id" smallint NOT NULL,
  "availability" smallint NOT NULL CHECK (availability IN (1, 2, 3, 4)),
  "details" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "equipment_id")
);

CREATE TABLE "variant_prices" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "price_type" smallint NOT NULL CHECK (price_type IN (1, 2, 3, 4)),
  "configuration_note" varchar(120),
  "currency_code" char(3) NOT NULL,
  "amount" decimal(15,2) NOT NULL CHECK (amount >= 0),
  "effective_date" date,
  "source_cell_id" integer,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "cost_metrics" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" varchar(40) UNIQUE NOT NULL,
  "description" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_costs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "metric_id" smallint NOT NULL,
  "value" decimal(16,4) NOT NULL CHECK (value >= 0),
  "unit" varchar(32) NOT NULL,
  "measured_on" date,
  "notes" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_commercial_terms" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "currency_code" char(3),
  "promotion" text,
  "dealer_support" text,
  "gross_margin_amount" decimal(15,2),
  "net_margin_amount" decimal(15,2),
  "gross_margin_pct" decimal(7,3),
  "net_margin_pct" decimal(7,3),
  "effective_date" date,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "warehouses" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "inventory_statuses" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(40) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_inventory" (
  "variant_id" integer NOT NULL,
  "warehouse_id" smallint NOT NULL,
  "status_id" smallint,
  "quantity" integer CHECK (quantity >= 0),
  "eta" date,
  "production_lead_time_days" smallint CHECK (production_lead_time_days >= 0),
  "observed_at" timestamp,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "warehouse_id")
);

CREATE TABLE "variant_finance_plans" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "currency_code" char(3) NOT NULL,
  "max_loan_amount" decimal(15,2) CHECK (max_loan_amount >= 0),
  "deposit_amount" decimal(15,2) CHECK (deposit_amount >= 0),
  "loan_amount" decimal(15,2) CHECK (loan_amount >= 0),
  "tenure_months" smallint CHECK (tenure_months > 0),
  "monthly_payment" decimal(15,2) CHECK (monthly_payment >= 0),
  "notes" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "use_cases" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_use_cases" (
  "variant_id" integer NOT NULL,
  "use_case_id" smallint NOT NULL,
  "role" smallint NOT NULL CHECK (role IN (1, 2, 3, 4, 5, 6)),
  "reason" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "use_case_id", "role")
);

CREATE TABLE "market_categories" (
  "id" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" smallint NOT NULL CHECK (kind IN (1, 2, 3)),
  "name" varchar(120) NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_market_categories" (
  "variant_id" integer NOT NULL,
  "category_id" smallint NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "category_id")
);

CREATE TABLE "variant_sales_arguments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "kind" smallint NOT NULL CHECK (kind IN (1, 2, 3, 4)),
  "position" smallint NOT NULL CHECK (position > 0),
  "content" text NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_competitors" (
  "variant_id" integer NOT NULL,
  "competitor_variant_id" integer NOT NULL,
  "advantage" text,
  "disadvantage" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  CHECK (variant_id <> competitor_variant_id),
  PRIMARY KEY ("variant_id", "competitor_variant_id")
);

CREATE TABLE "variant_warranties" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "scope" smallint NOT NULL CHECK (scope IN (1, 2, 3)),
  "months" smallint CHECK (months > 0),
  "distance_km" integer CHECK (distance_km > 0),
  "terms" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_service_intervals" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "months" smallint CHECK (months > 0),
  "distance_km" integer CHECK (distance_km > 0),
  "details" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_marketing" (
  "variant_id" integer PRIMARY KEY,
  "seo_title" varchar(255),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "tags" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(100) UNIQUE NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_tags" (
  "variant_id" integer NOT NULL,
  "tag_id" integer NOT NULL,
  "role" smallint NOT NULL CHECK (role IN (1, 2)),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "tag_id", "role")
);

CREATE TABLE "variant_recommendations" (
  "variant_id" integer PRIMARY KEY,
  "score" decimal(10,4),
  "score_definition" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "knowledge_entries" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" smallint NOT NULL CHECK (kind IN (1, 2)),
  "question_or_problem" text NOT NULL,
  "answer_or_solution" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "variant_knowledge" (
  "variant_id" integer NOT NULL,
  "knowledge_id" integer NOT NULL,
  "position" smallint CHECK (position > 0),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  PRIMARY KEY ("variant_id", "knowledge_id")
);

CREATE TABLE "variant_documents" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "variant_id" integer NOT NULL,
  "kind" smallint NOT NULL CHECK (kind IN (1, 2, 3, 4, 5, 6)),
  "url" text NOT NULL,
  "caption" text,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "import_files" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "file_name" varchar(255) NOT NULL,
  "sha256" char(64) UNIQUE NOT NULL,
  "source_modified_at" timestamp,
  "imported_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "import_records" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "file_id" integer NOT NULL,
  "sheet_name" varchar(31) NOT NULL,
  "block_key" varchar(40) NOT NULL DEFAULT '',
  "record_key" varchar(40) NOT NULL,
  "variant_id" integer,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "import_cells" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "record_id" integer NOT NULL,
  "cell_address" varchar(12) NOT NULL,
  "group_label" varchar(120),
  "field_name" varchar(120) NOT NULL,
  "field_description" text,
  "raw_value" text,
  "cell_type" varchar(16),
  "number_format" varchar(80),
  "formula" text,
  "comment" text,
  "parse_status" smallint NOT NULL CHECK (parse_status IN (0, 1, 2, 3)) DEFAULT 0,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "import_issues" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "cell_id" integer NOT NULL,
  "code" varchar(40) NOT NULL,
  "description" text NOT NULL,
  "resolution" text,
  "resolved_at" timestamp,
  "created_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE INDEX ON "vehicle_models" ("brand_id", "name");

CREATE INDEX ON "vehicle_variants" ("model_id");

CREATE INDEX ON "variant_engines" ("engine_id");

CREATE INDEX ON "variant_transmissions" ("transmission_id");

CREATE INDEX ON "variant_equipment" ("equipment_id");

CREATE INDEX ON "variant_prices" ("variant_id", "price_type", "effective_date");

CREATE INDEX ON "variant_costs" ("variant_id", "metric_id", "measured_on");

CREATE INDEX ON "variant_commercial_terms" ("variant_id", "effective_date");

CREATE INDEX ON "variant_inventory" ("warehouse_id");

CREATE INDEX ON "variant_finance_plans" ("variant_id");

CREATE INDEX ON "variant_use_cases" ("use_case_id");

CREATE UNIQUE INDEX ON "market_categories" ("kind", "name");

CREATE INDEX ON "variant_market_categories" ("category_id");

CREATE UNIQUE INDEX ON "variant_sales_arguments" ("variant_id", "kind", "position");

CREATE INDEX ON "variant_competitors" ("competitor_variant_id");

CREATE UNIQUE INDEX ON "variant_warranties" ("variant_id", "scope");

CREATE INDEX ON "variant_service_intervals" ("variant_id");

CREATE INDEX ON "variant_tags" ("tag_id");

CREATE INDEX ON "variant_knowledge" ("knowledge_id");

CREATE INDEX ON "variant_documents" ("variant_id", "kind");

CREATE UNIQUE INDEX ON "import_records" ("file_id", "sheet_name", "block_key", "record_key");

CREATE INDEX ON "import_records" ("variant_id");

CREATE UNIQUE INDEX ON "import_cells" ("record_id", "cell_address");

CREATE INDEX ON "import_issues" ("cell_id");

COMMENT ON COLUMN "chat_sessions"."id" IS 'UUID tạo từ Next.js LocalStorage';

COMMENT ON COLUMN "chat_sessions"."mode" IS 'BOT/HUMAN_PENDING/HUMAN_ACTIVE';

COMMENT ON COLUMN "customers"."phone_number" IS 'Dùng SĐT làm định danh chính';

COMMENT ON COLUMN "messages"."role" IS 'user, ai, tool';

COMMENT ON COLUMN "messages"."tool_calls" IS 'Lưu JSON payload nếu AI gọi tool';

COMMENT ON COLUMN "contracts"."pdf_url" IS 'Link tải file hợp đồng hiển thị trên Web';

COMMENT ON COLUMN "maintenance_reminders"."status" IS 'PENDING, NOTIFIED, COMPLETED';

COMMENT ON COLUMN "vehicle_models"."name" IS 'Không UNIQUE: tên model chưa đủ xác định cấu hình. NULL chỉ cho định danh tạm chưa có tên (ví dụ DONGBEN dòng 73); không gom các model thiếu tên theo brand.';

COMMENT ON TABLE "vehicle_variants" IS 'Một dòng hợp lệ sau làm sạch là một cấu hình. Không UNIQUE theo model, wheelbase hoặc engine; biến thể có thể khác tải trọng đăng kiểm.';

COMMENT ON COLUMN "vehicle_variants"."model_id" IS 'NULL khi chưa đủ định danh/Brand; Brand biết nhưng thiếu tên thì dùng model tạm name=NULL. Không tạo tên giả.';

COMMENT ON COLUMN "vehicle_variants"."vehicle_type_id" IS 'Loại xe/body thuộc cấu hình, không mặc định là thuộc tính cố định của model.';

COMMENT ON COLUMN "vehicle_variants"."product_code" IS 'Product_ID nguồn đang trống; không gán Model vào cột này.';

COMMENT ON COLUMN "vehicle_variants"."assembly_type" IS '1 CKD; 2 CBU; NULL chưa xác nhận.';

COMMENT ON COLUMN "vehicle_variants"."wheel_formula" IS 'Ví dụ 4x2R, 6x4; không ép thành số.';

COMMENT ON COLUMN "vehicle_variants"."curb_mass_basis" IS 'Qualifier nguyên nghĩa: chassis, vehicle,...; không suy ra từ Vehicle Type.';

COMMENT ON COLUMN "vehicle_variants"."payload_kg" IS 'Chỉ điền khi có một tải trọng xác nhận. Giá trị 990/1210 cần xác định cấu hình, không chọn tùy ý.';

COMMENT ON TABLE "variant_load_alternatives" IS 'Chỉ dùng khi nguồn công bố nhiều lựa chọn chưa tách được thành variant; để cột scalar tương ứng trong vehicle_variants là NULL. Application/trigger ngăn lưu cả scalar và alternative cho cùng đại lượng.';

COMMENT ON COLUMN "variant_load_alternatives"."kind" IS '1 payload; 2 gross vehicle mass. Các tập phương án độc lập, không ngầm ghép cặp.';

COMMENT ON COLUMN "variant_dimensions"."scope" IS '1 overall; 2 cargo; 3 cabin; 4 chassis. Không ngầm coi overall là chassis.';

